public void initFromUPSVendPriceAdmTrans(UPSVendPriceAdmTrans _upsVendPriceAdmTrans)
{
    this.AccountCode     = _upsVendPriceAdmTrans.AccountCode;
    this.AccountRelation = _upsVendPriceAdmTrans.AccountRelation;
    this.DefaultRelation = _upsVendPriceAdmTrans.DefaultRelation;
    this.ItemNum         = _upsVendPriceAdmTrans.ItemNum;
    this.NameSim         = _upsVendPriceAdmTrans.NameSim;
    this.UnitId          = _upsVendPriceAdmTrans.UnitId;
    this.Currency        = _upsVendPriceAdmTrans.Currency;
    this.FromDate        = _upsVendPriceAdmTrans.FromDate;
    this.ToDate          = _upsVendPriceAdmTrans.ToDate;
    this.Amount          = _upsVendPriceAdmTrans.Amount;
    this.PriceUnit       = _upsVendPriceAdmTrans.PriceUnit;
    this.Markup          = _upsVendPriceAdmTrans.Markup;
    this.JournalNum      = _upsVendPriceAdmTrans.JournalNum;
    this.InventDimId     = _upsVendPriceAdmTrans.InventDimId;
}

public InventDim inventDim(boolean  update = false)
{
    return InventDim::find(this.InventDimId, update);
}

    public void initValue()
    {
        super();

        this.PriceUnit = 1;
	}

public void preWrite()
{
    if (this.AccountCode == TableGroupAll::All)
    {
        this.AccountRelation = '';
    }
}

public void  insert()
{
    this.preWrite();

    super();
}

public void update()
{
    this.preWrite();

    super();
}

public TableExtension getExtension()
{
    return SysTableExtension::construct();
}

public container getDefaultingDependencies()
{
    return [[fieldnum(UPSVendPriceAdmTrans, AccountRelation), [fieldnum(UPSVendPriceAdmTrans, AccountCode)]],
            [fieldnum(UPSVendPriceAdmTrans, UnitId), [fieldnum(UPSVendPriceAdmTrans, ItemNum)]],
            [fieldnum(UPSVendPriceAdmTrans, Currency), [fieldnum(UPSVendPriceAdmTrans, AccountRelation)]]
           ];
}

public void defaultField(FieldId _fieldId)
{
    super(_fieldId);

    switch (_fieldId)
    {
        case fieldnum(UPSVendPriceAdmTrans, AccountRelation):
            this.defaultAccountRelation();
            break;

        case fieldnum(UPSVendPriceAdmTrans, UnitId):
            this.initFromItemCode();
            break;

        case fieldnum(UPSVendPriceAdmTrans, Currency):
            this.initFromAccountCode();
            break;
    }
}

private void defaultAccountRelation()
{
    if (this.AccountCode == TableGroupAll::All)
    {
        this.AccountRelation = '';
    }
}

public void initFromItemCode()
{
    InventTable inventTable;

    if (this.UnitId  &&  this.ItemNum == this.orig().ItemNum)
    {
        return;
    }

    inventTable = InventTable::find(this.ItemNum);

    this.UnitId =  inventTable.purchUnitId();
}

public void initFromAccountCode()
{
    VendTable   vendTable;

    if (this.AccountCode != TableGroupAll::Table)
    {
        return;
    }

    vendTable = VendTable::find(this.AccountRelation);
    this.Currency = vendTable.Currency;
}

public boolean validateField(FieldId  fieldId)
{
    boolean  ok = true;

    ok = super(fieldId);

    switch (fieldId)
    {
        case (fieldNum(UPSVendPriceAdmTrans, AccountRelation)) :   
            ok = this.checkAccountRelation();
            break;
    }

    return ok;
}

public boolean validateWrite()
{
    boolean  ok = true;

    ok = super();

    if (! this.checkDate())
        ok = false;

    if (! this.checkProductDimensions())
        ok = false;

    if (! this.checkAccountRelation())
        ok = false;

    if (! this.checkCurrency())
        ok = false;

    if (! this.checkUnitId())
        ok = false;

    return ok;
}

private boolean  checkDate()
{
    boolean  ok = true;

    if (this.ToDate < this.FromDate)
    {
        if (this.ToDate)
        {
            ok = checkFailed("@SYS16982");
        }
    }

    return ok;
}

protected boolean  checkProductDimensions()
{
    return this.inventDim().validateWriteProductDimensions(this.ItemNum, false);
}

protected boolean checkAccountRelation()
{
    boolean isOk = true;

    switch (this.AccountCode)
    {
        case TableGroupAll::Table :
            if (! this.checkAccountRelationTable())
            {
                isOk = checkFailed("@SYS4000121");
            }
            break;
        case TableGroupAll::GroupId :
            if (! this.checkVendPriceGroupExists())
            {
                isOk = checkFailed("@SYS4000121");
            }
            break;
        case TableGroupAll::All :
            if (this.AccountRelation)
            {
                isOk = checkFailed("@SYS4000121");
            }
            break;
    }

    return isOk;
}

protected boolean checkAccountRelationTable()
{
    if (this.AccountCode != TableGroupAll::Table)
    {
        return false;
    }

    return VendTable::exist(this.AccountRelation);
}

protected boolean checkVendPriceGroupExists()
{
    return UPSVendPriceGroup::exist(this.AccountRelation);
}

private boolean checkCurrency()
{
    boolean ok = true;

    if (this.Currency)
    {
        if (! Currency::exist(this.Currency))
        {
            ok = checkFailed(strFmt("@SYS1458", this.Currency));
        }
    }
    else
    {
        ok = checkFailed("@SYS23229");
    }

    return ok;
}

private boolean checkUnitId()
{
    boolean ok = true;

    if (this.UnitId)
    {
        if (! UnitOfMeasure::find(UnitOfMeasure::unitOfMeasureIdBySymbol(this.UnitId)))
        {
            ok = checkFailed(strFmt("@SYS4108", this.UnitId));
        }
    }

    return ok;
}
